"use client";

import { useEffect, useState, Suspense } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { Header } from "@/components/layouts/Header";
import { SearchBar } from "@/components/ui/SearchBar";
import { ProductGrid } from "@/components/features/ProductGrid";
import { zenserpService } from "@/services/zenserp.service";
import { productService } from "@/services/product.service";
import { IShoppingResult, IDummyProduct } from "@/interfaces/product.interface";

type SortOption = "price-asc" | "price-desc" | "rating";

// Helper to find the best matching image for a product title
function findMatchingImage(title: string, dummyProducts: IDummyProduct[]): string | undefined {
  if (dummyProducts.length === 0) return undefined;

  const titleLower = title.toLowerCase();
  const titleWords = titleLower.split(/\s+/).filter(w => w.length > 2);

  // Score each product by how many words match
  let bestMatch: IDummyProduct | null = null;
  let bestScore = 0;

  for (const product of dummyProducts) {
    const productTitle = product.title.toLowerCase();
    let score = 0;

    for (const word of titleWords) {
      if (productTitle.includes(word)) {
        score++;
      }
    }

    if (score > bestScore) {
      bestScore = score;
      bestMatch = product;
    }
  }

  // Return best match if we found any meaningful match, otherwise return first product's image
  return bestMatch?.thumbnail || dummyProducts[0]?.thumbnail;
}

function SearchContent() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const query = searchParams.get("q") || "";

  const [products, setProducts] = useState<IShoppingResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<SortOption>("price-asc");
  const [priceRange, setPriceRange] = useState({ min: 0, max: 0, avg: 0 });

  useEffect(() => {
    if (query) {
      fetchProducts(query);
    }
  }, [query]);

  const fetchProducts = async (searchQuery: string) => {
    setIsLoading(true);
    setError(null);

    try {
      // Fetch both Zenserp results and DummyJSON products in parallel
      const [zenserpResults, dummyProducts] = await Promise.all([
        zenserpService.searchProducts(searchQuery, 40),
        productService.searchProducts(searchQuery),
      ]);

      // If no dummy products found for specific query, try a broader search
      let imageProducts = dummyProducts;
      if (dummyProducts.length === 0) {
        // Try to get some generic products as fallback
        imageProducts = await productService.getFeaturedProducts(10);
      }

      // Attach matching images to Zenserp results
      const resultsWithImages = zenserpResults.map((result) => ({
        ...result,
        image: findMatchingImage(result.title, imageProducts),
      }));

      setProducts(resultsWithImages);
      setPriceRange(zenserpService.getPriceRange(resultsWithImages));
    } catch (err) {
      setError("Failed to fetch products. Please try again.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSearch = (newQuery: string) => {
    router.push(`/search?q=${encodeURIComponent(newQuery)}`);
  };

  const handleSort = (option: SortOption) => {
    setSortBy(option);

    let sortedProducts: IShoppingResult[];
    switch (option) {
      case "price-asc":
        sortedProducts = zenserpService.sortByPrice(products, true);
        break;
      case "price-desc":
        sortedProducts = zenserpService.sortByPrice(products, false);
        break;
      case "rating":
        sortedProducts = zenserpService.sortByRating(products);
        break;
      default:
        sortedProducts = products;
    }
    setProducts(sortedProducts);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-1 py-8 px-6">
        <div className="max-w-7xl mx-auto">
          {/* Search Bar */}
          <div className="mb-8">
            <SearchBar
              onSearch={handleSearch}
              initialValue={query}
              placeholder="Search for another product..."
              className="mx-auto"
            />
          </div>

          {/* Results Header */}
          {query && (
            <div className="mb-8">
              <h1 className="text-3xl font-black text-[var(--duo-text)] mb-2">
                Results for &quot;<span className="text-[var(--duo-green)]">{query}</span>&quot;
              </h1>

              {!isLoading && products.length > 0 && (
                <div className="flex flex-wrap items-center gap-4 mt-4">
                  {/* Price Range Summary */}
                  <div className="card-duo py-2 px-4 flex items-center gap-4">
                    <div className="text-center">
                      <div className="text-xs text-[var(--duo-text-muted)]">Lowest</div>
                      <div className="text-lg font-black text-[var(--duo-green)]">
                        ${priceRange.min.toFixed(2)}
                      </div>
                    </div>
                    <div className="w-px h-8 bg-[var(--duo-card-hover)]" />
                    <div className="text-center">
                      <div className="text-xs text-[var(--duo-text-muted)]">Average</div>
                      <div className="text-lg font-black text-[var(--duo-blue)]">
                        ${priceRange.avg.toFixed(2)}
                      </div>
                    </div>
                    <div className="w-px h-8 bg-[var(--duo-card-hover)]" />
                    <div className="text-center">
                      <div className="text-xs text-[var(--duo-text-muted)]">Highest</div>
                      <div className="text-lg font-black text-[var(--duo-red)]">
                        ${priceRange.max.toFixed(2)}
                      </div>
                    </div>
                  </div>

                  {/* Results count */}
                  <div className="text-[var(--duo-text-muted)]">
                    <span className="font-bold text-[var(--duo-text)]">{products.length}</span> products found
                  </div>

                  {/* Sort Dropdown */}
                  <div className="ml-auto flex items-center gap-2">
                    <span className="text-sm text-[var(--duo-text-muted)]">Sort by:</span>
                    <select
                      value={sortBy}
                      onChange={(e) => handleSort(e.target.value as SortOption)}
                      className="
                        bg-[var(--duo-card)] text-[var(--duo-text)]
                        font-bold rounded-[var(--duo-radius-sm)]
                        px-4 py-2 outline-none
                        border-2 border-transparent
                        focus:border-[var(--duo-green)]
                        cursor-pointer
                      "
                    >
                      <option value="price-asc">Price: Low to High</option>
                      <option value="price-desc">Price: High to Low</option>
                      <option value="rating">Best Rating</option>
                    </select>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Error State */}
          {error && (
            <div className="card-duo text-center py-12 mb-8 border border-[var(--duo-red)]">
              <span className="text-6xl mb-4 block">⚠️</span>
              <h3 className="text-xl font-bold text-[var(--duo-red)] mb-2">
                Oops! Something went wrong
              </h3>
              <p className="text-[var(--duo-text-muted)]">{error}</p>
              <button
                onClick={() => fetchProducts(query)}
                className="btn-duo mt-4"
              >
                Try Again
              </button>
            </div>
          )}

          {/* Products Grid */}
          <ProductGrid products={products} isLoading={isLoading} />

          {/* No query state */}
          {!query && !isLoading && (
            <div className="text-center py-16">
              <span className="text-8xl mb-6 block">🔍</span>
              <h2 className="text-2xl font-bold text-[var(--duo-text)] mb-2">
                Start Your Search
              </h2>
              <p className="text-[var(--duo-text-muted)]">
                Enter a product name above to compare prices
              </p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

export default function SearchPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center bg-[var(--duo-bg)]">
        <div className="text-center">
          <div className="text-6xl mb-4 animate-bounce">🔍</div>
          <p className="text-[var(--duo-text-muted)] font-bold">Loading...</p>
        </div>
      </div>
    }>
      <SearchContent />
    </Suspense>
  );
}

"use client";

import { FC, useState, KeyboardEvent } from "react";
import { ISearchBarProps } from "@/interfaces/product.interface";

export const SearchBar: FC<ISearchBarProps> = ({
  onSearch,
  placeholder = "Search for products...",
  initialValue = "",
  className = "",
}) => {
  const [query, setQuery] = useState(initialValue);
  const [isFocused, setIsFocused] = useState(false);

  const handleSearch = () => {
    if (query.trim()) {
      onSearch(query.trim());
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      handleSearch();
    }
  };

  return (
    <div
      className={`relative w-full max-w-2xl ${className}`}
    >
      <div
        className={`
          flex items-center gap-3 px-6 py-4
          bg-[var(--duo-card)] rounded-[var(--duo-radius-lg)]
          border-2 transition-all duration-300
          ${isFocused 
            ? "border-[var(--duo-green)] shadow-[0_0_30px_rgba(88,204,2,0.3)]" 
            : "border-transparent hover:border-[var(--duo-card-hover)]"
          }
        `}
      >
        {/* Search Icon */}
        <svg
          className={`w-6 h-6 transition-colors duration-300 ${
            isFocused ? "text-[var(--duo-green)]" : "text-[var(--duo-text-muted)]"
          }`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
          />
        </svg>

        {/* Input */}
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          placeholder={placeholder}
          className="
            flex-1 bg-transparent text-lg font-semibold
            text-[var(--duo-text)] placeholder:text-[var(--duo-text-muted)]
            outline-none
          "
        />

        {/* Search Button */}
        <button
          onClick={handleSearch}
          disabled={!query.trim()}
          className={`
            px-6 py-2 rounded-[var(--duo-radius-sm)] font-bold
            text-white uppercase tracking-wider text-sm
            transition-all duration-200
            ${query.trim()
              ? "bg-[var(--duo-green)] hover:bg-[var(--duo-green-light)] shadow-[var(--duo-shadow-green)] hover:translate-y-[-2px] active:translate-y-[2px] active:shadow-none"
              : "bg-[var(--duo-card-hover)] cursor-not-allowed"
            }
          `}
        >
          Compare
        </button>
      </div>

      {/* Animated underline */}
      <div
        className={`
          absolute bottom-0 left-1/2 -translate-x-1/2 h-1
          bg-gradient-to-r from-[var(--duo-green)] via-[var(--duo-blue)] to-[var(--duo-purple)]
          rounded-full transition-all duration-300
          ${isFocused ? "w-3/4 opacity-100" : "w-0 opacity-0"}
        `}
      />
    </div>
  );
};

