class ProductService {
  async getProductsByCategory(category: string): Promise<IDummyProduct[]> {
    try {
      const response = await fetch(
        `${DUMMYJSON_BASE_URL}/products/category/${category}`
      );

      if (!response.ok) {
        throw new Error(`DummyJSON API error: ${response.status}`);
      }

      const data: IDummyProductsResponse = await response.json();
      return data.products;
    } catch (error) {
      console.error("DummyJSON fetch error:", error);
      return [];
    }
  }

  async searchProducts(query: string): Promise<IDummyProduct[]> {
    try {
      const response = await fetch(
        `${DUMMYJSON_BASE_URL}/products/search?q=${encodeURIComponent(query)}`
      );

      if (!response.ok) {
        throw new Error(`DummyJSON API error: ${response.status}`);
      }

      const data: IDummyProductsResponse = await response.json();
      return data.products;
    } catch (error) {
      console.error("DummyJSON search error:", error);
      return [];
    }
  }

  async getCategories(): Promise<string[]> {
    try {
      const response = await fetch(`${DUMMYJSON_BASE_URL}/products/categories`);

      if (!response.ok) {
        throw new Error(`DummyJSON API error: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error("DummyJSON categories error:", error);
      return [];
    }
  }

  async getFeaturedProducts(limit: number = 8): Promise<IDummyProduct[]> {
    try {
      const response = await fetch(
        `${DUMMYJSON_BASE_URL}/products?limit=${limit}&skip=0`
      );

      if (!response.ok) {
        throw new Error(`DummyJSON API error: ${response.status}`);
      }

      const data: IDummyProductsResponse = await response.json();
      return data.products;
    } catch (error) {
      console.error("DummyJSON featured error:", error);
      return [];
    }
  }

  // Get a placeholder image URL based on search query
  getPlaceholderImage(query: string, width: number = 400, height: number = 400): string {
    // Use DiceBear for consistent placeholder avatars based on query
    const seed = encodeURIComponent(query.toLowerCase().replace(/\s+/g, "-"));
    return `https://api.dicebear.com/7.x/shapes/svg?seed=${seed}&backgroundColor=1A2C33`;
  }
}

