import { IZenserpResponse, IShoppingResult } from "@/interfaces/product.interface";

const ZENSERP_API_KEY = `${process.env.NEXT_PUBLIC_ZENSERP_API_KEY}`;
const ZENSERP_BASE_URL = "https://app.zenserp.com/api/v2/search";

class ZenserpService {
  async searchProducts(query: string, num: number = 10): Promise<IShoppingResult[]> {
    try {
      const params = new URLSearchParams({
        apikey: ZENSERP_API_KEY,
        q: query,
        tbm: "shop",
        num: "10",
      });

      const response = await fetch(`${ZENSERP_BASE_URL}?${params.toString()}`);

      if (!response.ok) {
        throw new Error(`Zenserp API error: ${response.status}`);
      }

      const data: IZenserpResponse = await response.json();

      // Mark the best deal (lowest price)
      const results = data.shopping_results || [];
      if (results.length > 0) {
        const lowestPrice = Math.min(
          ...results.map((r) => r.price_parsed?.value || Infinity)
        );

        return results.map((result) => ({
          ...result,
          isBestDeal: result.price_parsed?.value === lowestPrice,
        }));
      }

      return results;
    } catch (error) {
      console.error("Zenserp search error:", error);
      throw error;
    }
  }

  getPriceRange(results: IShoppingResult[]): { min: number; max: number; avg: number } {
    const prices = results
      .map((r) => r.price_parsed?.value)
      .filter((p): p is number => typeof p === "number" && p > 0);

    if (prices.length === 0) {
      return { min: 0, max: 0, avg: 0 };
    }

    const min = Math.min(...prices);
    const max = Math.max(...prices);
    const avg = prices.reduce((a, b) => a + b, 0) / prices.length;

    return { min, max, avg: Math.round(avg * 100) / 100 };
  }

  sortByPrice(results: IShoppingResult[], ascending: boolean = true): IShoppingResult[] {
    return [...results].sort((a, b) => {
      const priceA = a.price_parsed?.value || 0;
      const priceB = b.price_parsed?.value || 0;
      return ascending ? priceA - priceB : priceB - priceA;
    });
  }

  sortByRating(results: IShoppingResult[]): IShoppingResult[] {
    return [...results].sort((a, b) => (b.stars || 0) - (a.stars || 0));
  }
}

export const zenserpService = new ZenserpService();

