  const discountedPrice = product.price * (1 - product.discountPercentage / 100);

  return (
    <article
      onClick={handleClick}
      className={`
        card-duo group cursor-pointer
        flex flex-col h-full
        transition-all duration-300
        hover:scale-[1.02]
