        </div>
      </div>

      {/* Content */}
      <div className="flex-1 flex flex-col">
        {/* Brand Badge */}
        <span className="
          inline-block w-fit px-3 py-1 mb-2
          text-xs font-bold uppercase tracking-wider
          bg-[var(--duo-purple)]/20 text-[var(--duo-purple)]
          rounded-full
        ">
          {product.brand}
        </span>

        {/* Title */}
        <h3 className="
          text-base font-bold text-[var(--duo-text)]
          line-clamp-2 mb-2 flex-1
